import {it,expect} from 'vitest';
import {readFileSync,writeFileSync} from 'node:fs';
import {spawnSync} from 'node:child_process';
import {createEntity,newId} from '../src/domain/model';
import type {ProjectData} from '../src/domain/types';
import {dialogueContentHash} from '../src/domain/production';
import {bootstrapNativeProject,type AtomicSyncRepository,type ServerIdentity} from '../src/sync/server';
import {applyEditorOperation,readEditorImage} from '../src/sync/editor';
import {createSyncOperation} from '../src/sync/protocol';
import {assertAck} from '../src/sync/validation';
const root='/tmp/shinariokanri-independent-rb09-cfaebcb/independent',container='shinariokanri-independent-rb09-cfaebcb',owner:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000001',sessionId:'10000000-0000-4000-8000-000000000001'},editor:ServerIdentity={accountId:'00000000-0000-4000-8000-000000000002',sessionId:'10000000-0000-4000-8000-000000000002'},calls:unknown[]=[];
function arg(v:unknown):string{if(v===null)return'null';if(v&&typeof v==='object'&&'rawSQL'in v)return(v as {rawSQL:string}).rawSQL;return"'"+(typeof v==='object'?JSON.stringify(v):String(v)).replace(/'/g,"''")+"'"+(typeof v==='object'?'::jsonb':'');}
function sql(text:string){const r=spawnSync('docker',['exec','-i',container,'psql','-U','postgres','-qAt','-v','ON_ERROR_STOP=1'],{input:text,encoding:'utf8',timeout:20000,maxBuffer:32*1024*1024});calls.push({sql:text,status:r.status,stdout:r.stdout,stderr:r.stderr});writeFileSync(root+'/sql-derived-calls.json',JSON.stringify(calls,null,2)+'\n');if(r.status!==0)throw Error(r.stderr||'SQL_CALL_FAILED');return r.stdout;}
function rpc(name:string,values:unknown[]){const text=sql('set role service_role;\nselect public.'+name+'('+values.map(arg).join(',')+')::text;\n').trim();return text?JSON.parse(text):null;}
const repository:AtomicSyncRepository={read:async(i,p,b,o)=>rpc('scenario_sync_engine_context',[i.accountId,i.sessionId,p,b,o]),bootstrap:async(i,v)=>rpc('scenario_sync_bootstrap',[i.accountId,i.sessionId,v.project.projectId,v.project,v.documents,v.worlds]),commit:async(i,v)=>rpc('scenario_sync_commit_prepared',[i.accountId,i.sessionId,v.projectId,v.expectedRevision,v.operation,v.operationHash,v.ack,v.documents,v.image,{rawSQL:'ARRAY['+(v.derivedIds??[]).map(id=>"'"+id+"'").join(',')+']::uuid[]'}])};
function proof(id:string,data:unknown){writeFileSync(root+'/fixtures/'+id+'.json',JSON.stringify(data,null,2)+'\n');}
async function seed(){const f=JSON.parse(readFileSync(root+'/fixtures/native-two-targets.json','utf8')) as {p:ProjectData;idA:string;idB:string};f.p.projectId=newId();for(const e of f.p.entities)e.projectId=f.p.projectId;const blockId=newId(),line=createEntity(f.p.projectId,'dialogue_line','許可台詞',{text:[{id:blockId,kind:'paragraph',text:'A😀B'}],cueIds:[]});line.status='confirmed';line.visibility='team';f.p.entities.push(line);const locale=createEntity(f.p.projectId,'localization','PRIVATE_TRANSLATION_CANARY',{sourceLineId:line.id,language:'en',sourceHash:await dialogueContentHash(f.p,line),text:[{id:newId(),kind:'paragraph',text:'translation'}],stage:'reviewed',recordingIds:[]});locale.visibility='private';locale.status='confirmed';f.p.entities.push(locale);const dependent=f.p.entities.find(e=>e.id===f.idB)!;if(dependent.kind!=='note')throw Error('INVALID_FIXTURE_KIND');dependent.visibility='private';dependent.name='PRIVATE_ANCHOR_CANARY';dependent.data.body=[{id:newId(),kind:'paragraph',text:'参照',links:[{start:0,end:1,target:{entityId:line.id,blockId,start:1,end:2}}]}];await bootstrapNativeProject(repository,owner,{project:f.p,worlds:{}});rpc('scenario_membership',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,'editor',null,false,{rawSQL:'array[]::uuid[]'},0]);rpc('scenario_editor_grants',[owner.accountId,owner.sessionId,f.p.projectId,editor.accountId,[{id:line.id,fields:['data.text']}],1,1]);const image=await readEditorImage(repository,editor,f.p.projectId),base=image.documents[0],local=structuredClone(base);(local.fields['data.text'] as {text:string}[])[0].text='ZA😀B';const operation=await createSyncOperation({scope:{accountId:editor.accountId,projectId:f.p.projectId},baseRevision:'1',operationId:newId(),targets:[{base,local}],reason:'Unicode前置と原文改訂'});return {...f,lineId:line.id,localeId:locale.id,blockId,operation};}
it('R9DSV01 limited source edit atomically shifts private Unicode references and invalidates approved translation while keeping derived review and private IDs out of the editor ACK',async()=>{const f=await seed(),before=await repository.read(owner,f.p.projectId,null,null),capturing:AtomicSyncRepository={...repository,commit:async(i,v)=>{proof('R9SQL04-commit',{before,candidate:v,oldIds:before.documents.map(d=>d.id),newIds:v.documents.map(d=>d.id),lastCandidateId:v.documents.at(-1)?.id});return repository.commit(i,v);}};let ack;try{ack=await applyEditorOperation(capturing,editor,f.operation);}catch(cause){proof('R9SQL04-refused',{error:String(cause),before,after:await repository.read(owner,f.p.projectId,null,f.operation.operationId)});throw cause;}await assertAck(f.operation,ack);expect(ack.status).toBe('applied');expect(JSON.stringify(ack)).not.toMatch(/PRIVATE_|localization|review/);expect(JSON.stringify(ack)).not.toContain(f.idB);expect(JSON.stringify(ack)).not.toContain(f.localeId);const state=await repository.read(owner,f.p.projectId,null,null),dependent=state.nativeImage.entities.find(e=>e.id===f.idB),locale=state.nativeImage.entities.find(e=>e.id===f.localeId);expect(dependent?.kind==='note'&&dependent.data.body?.[0].links?.[0].target).toMatchObject({entityId:f.lineId,blockId:f.blockId,start:2,end:3});expect(locale?.kind==='localization'&&locale.data.stage).toBe('needs_review');expect(state.nativeImage.entities.some(e=>e.kind==='review'&&e.data.target===f.localeId&&e.visibility==='private'&&e.data.stage==='open')).toBe(true);expect(await applyEditorOperation(repository,editor,f.operation)).toEqual(ack);proof('R9DSV01',{operation:f.operation,ack,ownerState:state,classification:'Actual SQL migration6 + typed engine; synthetic Auth; no real DataAPI'});});
it('R9DSV02 a grant withdrawn after derived computation refuses source, private anchors, translation state and generated reviews together under the locked prepared RPC',async()=>{const f=await seed(),before=await repository.read(owner,f.p.projectId,null,null),revoking:AtomicSyncRepository={...repository,commit:async(i,v)=>{sql("update scenario_private.editor_scopes set revoked_at=now() where project_id='"+f.p.projectId+"' and account_id='"+editor.accountId+"';");return repository.commit(i,v);}};await expect(applyEditorOperation(revoking,editor,f.operation)).rejects.toThrow('FORBIDDEN');const after=await repository.read(owner,f.p.projectId,null,f.operation.operationId);expect(after.serverRevision).toBe('1');expect(after.nativeImage).toEqual(before.nativeImage);expect(after.documents).toEqual(before.documents);expect(after.previousAck).toBe(null);proof('R9DSV02',{before,after,allDerivedRefusedAtomically:true});});
it('R9DSV03 ordinary authenticated callers cannot execute service-only native/derived prepared commits even with valid UUIDs',()=>{expect(()=>sql("set role authenticated;\nselect public.scenario_sync_commit_prepared('"+editor.accountId+"','"+editor.sessionId+"','"+newId()+"',1,'{}'::jsonb,'sha256:fixture','{}'::jsonb,'[]'::jsonb,'{}'::jsonb,array[]::uuid[]);\n")).toThrow('permission denied');proof('R9DSV03',{ordinaryRoleNativeImageDerivedRpcDenied:true});});
